import{_ as r,c as e,o as l,ae as i}from"./chunks/framework.Dh1jimFm.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/shopify/apps/Dev Dashboard/Dev Dashboard.md","filePath":"docs/shopify/apps/Dev Dashboard/Dev Dashboard.md"}'),o={name:"docs/shopify/apps/Dev Dashboard/Dev Dashboard.md"};function t(s,a,d,p,h,n){return l(),e("div",null,a[0]||(a[0]=[i('<blockquote><p>Dev Dashboard是需要先注册合作伙伴账户吗</p></blockquote><p>不一定「先」注册合作伙伴账户，但实际开发时通常还是离不开 Partner 账户。先把官方文档给你：<a href="https://shopify.dev/docs/apps/build/dev-dashboard" target="_blank" rel="noreferrer">Dev Dashboard 介绍和入口</a>。</p><h3 id="_1-dev-dashboard-能从哪儿进入" tabindex="-1">1. Dev Dashboard 能从哪儿进入？ <a class="header-anchor" href="#_1-dev-dashboard-能从哪儿进入" aria-label="Permalink to &quot;1. Dev Dashboard 能从哪儿进入？&quot;">​</a></h3><p>根据文档，Dev Dashboard 有三种入口（docs）：</p><ul><li><p>直接访问：<a href="https://dev.shopify.com/dashboard" target="_blank" rel="noreferrer">https://dev.shopify.com/dashboard</a></p></li><li><p>从任意商家后台（Shopify Admin）进入：</p><ol><li>打开你的店铺后台</li><li>右上角点店铺名称</li><li>选择 “Dev Dashboard”</li></ol></li><li><p>从 Partner Dashboard（合作伙伴后台）进入：</p><ol><li>打开 Partner Dashboard</li><li>左侧点 “App distribution”</li><li>再点 “Visit Dev Dashboard”</li></ol></li></ul><p>从这里可以看出：</p><ul><li><p>你可以只用商家店铺账户，从 Admin 进入 Dev Dashboard，理论上不强制先有 Partner 账户。</p></li><li><p>但如果你要做应用分发、上架、收益结算等，就需要有 Shopify Partner 账户 和 Partner Dashboard，这时候 Dev Dashboard 也是从 Partner Dashboard 进去的。</p></li></ul><h3 id="_2-哪些场景不一定需要-partner-账户" tabindex="-1">2. 哪些场景不一定需要 Partner 账户？ <a class="header-anchor" href="#_2-哪些场景不一定需要-partner-账户" aria-label="Permalink to &quot;2. 哪些场景不一定需要 Partner 账户？&quot;">​</a></h3><p>在以下这些相对「个人/内部使用」的场景下，你可以先用自己的店铺账号 + Dev Dashboard 做开发：</p><ul><li>给自己店铺做私有/定制应用开发，只在自家店里用</li><li>在 Dev Dashboard 里： <ul><li>创建应用</li><li>创建 dev store（开发测试店铺）</li><li>在 dev store 上安装和调试你的 app</li></ul></li></ul><p>这些都可以只依赖你的 Shopify 账号 + Dev Dashboard 完成。</p><h3 id="_3-哪些场景一定要-partner-账户" tabindex="-1">3. 哪些场景一定要 Partner 账户？ <a class="header-anchor" href="#_3-哪些场景一定要-partner-账户" aria-label="Permalink to &quot;3. 哪些场景一定要 Partner 账户？&quot;">​</a></h3><p>一旦涉及到下面这些，基本就需要先注册 Partner 账户（Partner 体系 docs 示例）：</p><ul><li>想把 app 分发给其他商家（公有应用、定制应用的标准分发流程）</li><li>想把应用上架到 Shopify App Store</li><li>需要通过 Partner 体系来： <ul><li>查看和管理 app 的收入、结算</li><li>使用 Partner API 做自动化</li><li>管理团队、组织身份等</li></ul></li></ul><p>在这些场景里，Dev Dashboard 和 Partner Dashboard 是配套使用的： Partner Dashboard 负责「账号/组织/收益/分发」层面； Dev Dashboard 负责「应用开发、监控、日志、dev store」层面。</p><h3 id="_4-实际建议的顺序" tabindex="-1">4. 实际建议的顺序 <a class="header-anchor" href="#_4-实际建议的顺序" aria-label="Permalink to &quot;4. 实际建议的顺序&quot;">​</a></h3><p>如果你只是想先研究一下：</p><ol><li>有一个 Shopify 店铺账号（可以是开发用的店铺）。</li><li>直接访问 dev.shopify.com/dashboard 看看是否能进入 Dev Dashboard，创建一个测试 app 和 dev store 玩一玩。</li></ol><p>如果你已经确定要做「给客户/他人使用」「上架 app store」：</p><ol><li>先注册 Shopify Partner 账户（免费）。</li><li>在 Partner Dashboard 中： <ul><li>创建组织</li><li>之后通过 “App distribution → Visit Dev Dashboard” 进入 Dev Dashboard 管理 app。</li></ul></li></ol><p>如果你方便说一下目前的目标（比如「给自己店用的 app」还是「准备做商用/上架」），我可以按你的情况具体说：</p><ul><li>要不要立即办 Partner 账户</li><li>推荐的账号结构（个人 vs 公司组织）</li><li>接下来在 Dev Dashboard 里的操作路径。</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><ol><li>不需要走Partner账户这个Channel了</li><li>需要具有给员工配置Organization级别权限的账号才能配置Dev Bashboard的访问权限</li></ol>',24)]))}const v=r(o,[["render",t]]);export{b as __pageData,v as default};
